FLAT = [x for part in S for x in part]
SIZES = [2, 2, 8, 5, 3]
S = []
_i = 0
for n in SIZES:
    S.append(FLAT[_i:_i+n]); _i += n
assert _i == len(FLAT), (_i, len(FLAT))
def _build(lang):
    idx = 0 if lang == "vi" else 1
    parts = []
    for part in S:
        slides = []
        for (tv, te, bv, be, ev, ee, img) in part:
            d = {"title": tv if idx == 0 else te, "body": bv if idx == 0 else be, "explain": ev if idx == 0 else ee}
            if img: d["img"] = img
            slides.append(d)
        parts.append(slides)
    return parts
SLIDES = {"vi": _build("vi"), "en": _build("en")}
